    public class MECommandsController : BaseBusinessController
    {
        public MECommandsController()
        {
            dal = new DALBaseProvider("MECommands", typeof(MECommandsInfo));
        }

        public DataSet GetAllCommands()
        {
            DataSet ds = dal.GetDataSet("MECommands_GetAllCommands");
            return ds;
        }

        /// <summary>
        /// Get all command
        /// </summary>
        /// <returns>List of the command</returns>
        public List<MECommandsInfo> GetAllCommandList()
        {
            List<MECommandsInfo> commandList = new List<MECommandsInfo>();
            DataSet ds = GetAllCommands();
            if (ds.Tables[0].Rows.Count > 0)
            {
                foreach (DataRow row in ds.Tables[0].Rows)
                {
                    MECommandsInfo objCommandsInfo = (MECommandsInfo)GetObjectFromDataRow(row);
                    commandList.Add(objCommandsInfo);
                }
            }
            return commandList;
        }

