        }

        /// <summary>
        /// Get max command sort order
        /// </summary>
        /// <returns>Max sort order</returns>
        public int GetMaxCommandSortOrder()
        {
            int max = 0;
            DataSet ds = dal.GetDataSet("MECommands_GetMaxCommandSortOrder");
            if (ds.Tables[0].Rows.Count > 0)
            {
                MECommandsInfo objCommandsInfo = (MECommandsInfo)GetObjectFromDataRow(ds.Tables[0].Rows[0]);
                max = objCommandsInfo.MECommandMaxSortOrder;
            }
